USE adaptivelearn;
CREATE TABLE student_concept_mastery (student_id CHAR(36) NOT NULL, concept_id CHAR(36) NOT NULL, score DECIMAL(5,2) NOT NULL DEFAULT 0, evidence_count INT UNSIGNED NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(student_id,concept_id), CONSTRAINT fk_mastery_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_mastery_concept FOREIGN KEY(concept_id) REFERENCES concepts(id) ON DELETE CASCADE);
CREATE TABLE assessment_problems (id CHAR(36) PRIMARY KEY, concept_id CHAR(36) NOT NULL, title VARCHAR(160) NOT NULL, prompt TEXT NOT NULL, language ENUM('java','python','cpp') NOT NULL DEFAULT 'java', starter_code MEDIUMTEXT NOT NULL, created_by CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_problem_concept FOREIGN KEY(concept_id) REFERENCES concepts(id) ON DELETE RESTRICT, CONSTRAINT fk_problem_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE submissions (id CHAR(36) PRIMARY KEY, problem_id CHAR(36) NOT NULL, student_id CHAR(36) NOT NULL, language ENUM('java','python','cpp') NOT NULL, code_snapshot MEDIUMTEXT NOT NULL, evaluation_mode ENUM('development_predefined','isolated_runner') NOT NULL, status ENUM('passed','failed','error','pending') NOT NULL, score DECIMAL(5,2) NOT NULL DEFAULT 0, duration_ms INT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_submissions_student(student_id,created_at), CONSTRAINT fk_submission_problem FOREIGN KEY(problem_id) REFERENCES assessment_problems(id) ON DELETE RESTRICT, CONSTRAINT fk_submission_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE submission_test_results (id CHAR(36) PRIMARY KEY, submission_id CHAR(36) NOT NULL, test_name VARCHAR(120) NOT NULL, passed BOOLEAN NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT TRUE, feedback VARCHAR(255) NOT NULL, CONSTRAINT fk_test_submission FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE);
CREATE TABLE coding_sessions (id CHAR(36) PRIMARY KEY, student_id CHAR(36) NOT NULL, problem_id CHAR(36) NOT NULL, privacy_notice_accepted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, INDEX idx_session_student(student_id), CONSTRAINT fk_session_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_session_problem FOREIGN KEY(problem_id) REFERENCES assessment_problems(id) ON DELETE CASCADE);
CREATE TABLE code_events (id CHAR(36) PRIMARY KEY, session_id CHAR(36) NOT NULL, event_type ENUM('edit','paste','run','submit','error','focus') NOT NULL, code_before MEDIUMTEXT NULL, code_after MEDIUMTEXT NULL, event_data JSON NULL, occurred_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_event_session_time(session_id,occurred_at), CONSTRAINT fk_event_session FOREIGN KEY(session_id) REFERENCES coding_sessions(id) ON DELETE CASCADE);
CREATE TABLE integrity_signals (id CHAR(36) PRIMARY KEY, submission_id CHAR(36) NOT NULL, signal_type VARCHAR(80) NOT NULL, severity ENUM('info','review') NOT NULL, explanation TEXT NOT NULL, event_ids JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_signal_submission FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE);
CREATE TABLE integrity_reviews (id CHAR(36) PRIMARY KEY, submission_id CHAR(36) NOT NULL, trainer_id CHAR(36) NOT NULL, status ENUM('not_reviewed','no_concern','discussion_required') NOT NULL DEFAULT 'not_reviewed', note TEXT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_review_submission(submission_id), CONSTRAINT fk_review_submission FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE, CONSTRAINT fk_review_trainer FOREIGN KEY(trainer_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE viva_questions (id CHAR(36) PRIMARY KEY, submission_id CHAR(36) NOT NULL, concept_id CHAR(36) NOT NULL, excerpt TEXT NOT NULL, question TEXT NOT NULL, expected_keywords JSON NOT NULL, modification TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_viva_submission FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE, CONSTRAINT fk_viva_concept FOREIGN KEY(concept_id) REFERENCES concepts(id) ON DELETE RESTRICT);
CREATE TABLE viva_answers (id CHAR(36) PRIMARY KEY, question_id CHAR(36) NOT NULL, student_id CHAR(36) NOT NULL, explanation TEXT NOT NULL, evaluation ENUM('understood','misconception','needs_review') NOT NULL, rationale TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_viva_answer(question_id,student_id), CONSTRAINT fk_answer_question FOREIGN KEY(question_id) REFERENCES viva_questions(id) ON DELETE CASCADE, CONSTRAINT fk_answer_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
